import { isPrimaryPointer } from "motion-dom";
export function extractEventInfo(event) {
    return {
        point: {
            x: event.pageX,
            y: event.pageY,
        },
    };
}
export const addPointerInfo = (handler) => {
    return (event) => {
        const pointer = event;
        if (isPrimaryPointer(pointer))
            handler(pointer, extractEventInfo(pointer));
    };
};
