import { createEffect, createSignal } from "solid-js";
import { getCurrentTreeVariants } from "./utils";
export function createMotionContext(props, parentContext) {
    const [initial, setInitial] = createSignal();
    const [animate, setAnimate] = createSignal();
    createEffect(() => {
        const variants = getCurrentTreeVariants(props, parentContext);
        setInitial(variants.initial);
        setAnimate(variants.animate);
    });
    return {
        get initial() {
            return initial();
        },
        get animate() {
            return animate();
        },
    };
}
