import { lowercaseSVGElements } from "../svg/lowercase-elements";
export function isSVGComponent(Component) {
    if (typeof Component !== "string" || Component.includes("-")) {
        return false;
    }
    if (lowercaseSVGElements.indexOf(Component) > -1 || /[A-Z]/u.test(Component)) {
        return true;
    }
    return false;
}
