// Motion builds CSSStyleDeclaration-shaped objects. Solid applies style objects
// with setProperty(), which requires CSS property names (including vendor prefixes).
export function toSolidStyle(style) {
    const result = {};
    for (const key in style) {
        const name = key.startsWith("--")
            ? key
            : key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`).replace(/^ms-/, "-ms-");
        result[name] = style[key];
    }
    return result;
}
